/** static bool32 RecordTrainerId(u32 trainerId, u32 *trainerIds, int size) */
export function RecordTrainerId(trainerId: any, trainerIds: any, size: any): any {
  let i, j;

      for (i = 0; i < size; i++)
      {
          if (trainerIds[i] == trainerId)
              break;
      }

      if (i == size)
      {
           
          for (j = size - 1; j > 0; j--)
              trainerIds[j] = trainerIds[j - 1];

          trainerIds[0] = trainerId;
          return TRUE;
      }
      else
      {
           
          for (j = i; j > 0; j--)
              trainerIds[j] = trainerIds[j - 1];

          trainerIds[0] = trainerId;
          return FALSE;
      }
}

